from gmpy2 import *

N = mpz()

e = mpz(65537)

A = iroot(N, 2)[0] + 1

x = iroot(mpz(A ** 2) - N, 2)[0]

p = A - x
q = A + x

phi_n = (p - 1) * (q - 1)

# Compute the private key
d = invert(e, phi_n)

ciphertext = mpz()


# Decrypt the ciphertext
plaintext = pow(ciphertext, d, N)

# PKCS 1.5 Decoding
plaintext_bytes = plaintext.to_bytes(256, "big")

for i in range(len(plaintext_bytes)):
    if plaintext_bytes[i] == ord(b"\x02"):
        plaintext_bytes = plaintext_bytes[i:]
        break

message = None

for i in range(len(plaintext_bytes)):
    if plaintext_bytes[i] == ord(b"\x00"):
        message = plaintext_bytes[i:].decode()
        break

print(message)
